 static void EnsureModel(string endpoint,string name){var d=Json.Read(Core.Net(endpoint.TrimEnd('/')+"/models",null,8));object val;if(!d.TryGetValue("data",out val)||!((System.Collections.IEnumerable)val).Cast<object>().Any(x=>Json.Str((Dictionary<string,object>)x,"id")==name))throw new Exception("The server is running but does not list model '"+name+"'. Check the model name.");}
