 void ResolveModel(){EnsureDirs();string language=Sel(lang);if(language==""||language=="reset")language=Directory.Exists(root.Text.Trim())?Profanity.CurrentLanguage(root.Text.Trim()):"en";string resolved=ModelCatalog.Resolve(Sel(modelMode),language,Path.Combine(assets,"LLM"),llm.Text.Trim(),swear.SelectedIndex==0&&Directory.Exists(root.Text.Trim())?Profanity.CurrentLevel(root.Text.Trim()):swear.SelectedIndex);if(resolved==null){using(var d=new OpenFileDialog{InitialDirectory=Path.Combine(assets,"LLM"),Filter="LLM model|*.gguf",Title="Choose a model to start"}){if(d.ShowDialog()!=DialogResult.OK)throw new Exception("Launch cancelled.");resolved=d.FileName;modelMode.SelectedIndex=3;}}llm.Text=resolved;if((swear.SelectedIndex==1||swear.SelectedIndex==5)&&Path.GetFileName(resolved).IndexOf("2B",StringComparison.OrdinalIgnoreCase)>=0)Say("2B may ignore tone or clean-language rules. Select 4B for more consistent roleplay.");if(!File.Exists(runtime.Text.Trim())){var engines=Directory.GetFiles(Path.Combine(assets,"LLM Runtime"),"llama-server.exe",SearchOption.AllDirectories);if(engines.Length==1)runtime.Text=engines[0];}}
 async Task StartServer(){ResolveModel();if(server!=null&&!server.HasExited){if(String.Equals(runningModel,Path.GetFullPath(llm.Text),StringComparison.OrdinalIgnoreCase)){Say("This local LLM is already running.");return;}Core.GameClosed();StopServer();}server=await Engine.Start(llm.Text,runtime.Text,Sel(ctx),Sel(gpu),Say);runningModel=Path.GetFullPath(llm.Text);SavePrefs();Say("Ready: "+Path.GetFileName(llm.Text)+". Keep the helper open during play.");}
 string runningModel="";
 void StopServer(){if(server!=null){if(!server.HasExited){server.Kill();server.WaitForExit(10000);}server.Dispose();server=null;Say("Stopped only the LLM started by this helper.");}}
 async Task Unpack(){EnsureDirs();await Task.Run(()=>{int count=0;foreach(string kind in new[]{"LLM","Whisper","LLM Runtime"}){string folder=Path.Combine(assets,kind);foreach(string zip in Directory.GetFiles(folder,"*.zip")){if(Path.GetFileName(zip).StartsWith("AI-NPC-Cyberpunk-Mod-",StringComparison.OrdinalIgnoreCase))throw new Exception("Archive "+Path.GetFileName(zip)+" belongs to another mod and cannot be installed in NightCityNet.");using(var z=ZipFile.OpenRead(zip)){foreach(var e in z.Entries){string clean=e.FullName.Replace('\\','/');if(clean.StartsWith("/")||clean.Split('/').Any(x=>x=="..")||clean.Contains(":"))throw new Exception("Unsafe path inside ZIP. Extraction stopped.");if(clean.IndexOf("AiNpcCyberpunkMod",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("This archive belongs to another AI mod. Extraction stopped.");}foreach(var e in z.Entries){string file=Path.GetFileName(e.FullName.Replace('\\','/'));bool allowed=kind=="LLM"?file.EndsWith(".gguf",StringComparison.OrdinalIgnoreCase):kind=="Whisper"?System.Text.RegularExpressions.Regex.IsMatch(file,@"^ggml-[a-zA-Z0-9_.-]+\.bin$"):(file=="llama-server.exe"||System.Text.RegularExpressions.Regex.IsMatch(file,@"^(ggml.*|llama.*|cublas.*|cudart.*|libomp.*|vcruntime.*|msvcp.*)\.dll$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)||file.StartsWith("LICENSE",StringComparison.OrdinalIgnoreCase));if(!allowed)continue;string target=Path.Combine(folder,file);Core.Under(target,folder);if(File.Exists(target)){Say("Already exists, skipping: "+file);continue;}string temp=target+".tmp-"+Guid.NewGuid().ToString("N");try{Say("Extracting: "+file);using(var input=e.Open())using(var output=File.Create(temp))input.CopyTo(output);if(new FileInfo(temp).Length!=e.Length)throw new Exception("Incomplete file in ZIP.");File.Move(temp,target);count++;}finally{if(File.Exists(temp))File.Delete(temp);}}}}}Say("Files prepared: "+count+". Original archives were kept.");});FindModels();}
 async Task TestLlm(){Say("Testing a short local LLM response...");string body=Json.Write(new Dictionary<string,object>{{"model","nightcitynet-local"},{"messages",new[]{new Dictionary<string,object>{{"role","user"},{"content","Reply with exactly OK."}}}},{"max_tokens",12},{"stream",false},{"temperature",0}});string result=await Task.Run(()=>Core.Net("http://127.0.0.1:17862/v1/chat/completions",body,90));var d=Json.Read(result);var choices=((System.Collections.IEnumerable)d["choices"]).Cast<object>().ToArray();var choice=(Dictionary<string,object>)choices[0];Say("Response: "+Json.Str(Json.Obj(choice,"message"),"content"));}
 void LoadPrefs(){Safe(()=>{string f=Path.Combine(Core.Base,"settings.user.json");if(!File.Exists(f))return;var p=Json.Read(File.ReadAllText(f));root.Text=Json.Str(p,"game");if(p.ContainsKey("apply_city_setup"))cityEnabled.Checked=Json.Str(p,"apply_city_setup").Equals("True",StringComparison.OrdinalIgnoreCase);llm.Text=Json.Str(p,"llm");runtime.Text=Json.Str(p,"runtime");whisper.Text=Json.Str(p,"whisper");int endingValue;if(Int32.TryParse(Json.Str(p,"ending_mode"),out endingValue)&&endingValue>=0&&endingValue<=2)endingSlider.Value=endingValue;if(p.ContainsKey("apply_endings"))endingEnabled.Checked=Json.Str(p,"apply_endings").Equals("True",StringComparison.OrdinalIgnoreCase);foreach(Choice choice in modelMode.Items)if(choice.Value==Json.Str(p,"model_mode"))modelMode.SelectedItem=choice;foreach(Choice choice in gpu.Items)if(choice.Value==Json.Str(p,"gpu_layers"))gpu.SelectedItem=choice;foreach(Choice choice in ctx.Items)if(choice.Value==Json.Str(p,"context"))ctx.SelectedItem=choice;});}
 void SavePrefs(){if(capture)return;Safe(()=>File.WriteAllText(Path.Combine(Core.Base,"settings.user.json"),Json.Write(new Dictionary<string,object>{{"game",root.Text},{"apply_city_setup",cityEnabled.Checked},{"llm",llm.Text},{"runtime",runtime.Text},{"whisper",whisper.Text},{"ending_mode",endingSlider.Value},{"apply_endings",endingEnabled.Checked},{"model_mode",Sel(modelMode)},{"gpu_layers",Sel(gpu)},{"context",Sel(ctx)}}),new UTF8Encoding(false)));}
}
static class Program {
 [STAThread]static int Main(string[] args){try{if(args.Length>0&&args[0]=="--self-test")return Tests.Run(args.Length>1?args[1]:Path.Combine(Core.Base,"test-data"));Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length>3&&args[0]=="--model-check"){try{Engine.Check(args[1],args[2],args[3]).GetAwaiter().GetResult();return 0;}catch(Exception e){File.WriteAllText(args[3]+".error.txt",e.ToString());return 1;}}if(args.Length>1&&args[0]=="--screenshot"){using(var f=new MainForm(true)){f.Show();f.Refresh();Application.DoEvents();using(var b=new Bitmap(f.ClientSize.Width,f.ClientSize.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,f.ClientSize));b.Save(args[1]);}f.Hide();}return 0;}var main=new MainForm(false);if(args.Length>0&&args[0]=="--start-local")main.Shown+=(s,e)=>main.StartLocal();Application.Run(main);return 0;}catch(Exception e){if(args.Length>0){File.WriteAllText(Path.Combine(Core.Base,"CLI-ERROR.txt"),e.ToString());if(args[0]=="--self-test"&&args.Length>1)File.WriteAllText(Path.Combine(args[1],"ERROR.txt"),e.ToString());Console.Error.WriteLine(e.Message);return 1;}MessageBox.Show(e.Message,"NightCityNet Helper");return 1;}}
}
}
